 setDifficulty(d:Difficulty){if(!['easy','normal','hard'].includes(d))return;const old=this.difficultyStats(),next=this.difficultyStats(d);for(const e of this.s.enemies){e.hp*=next.hp/old.hp;e.maxHp*=next.hp/old.hp;e.shield*=next.hp/old.hp;if(e.parts){e.parts.hangar*=next.hp/old.hp;e.parts.missiles*=next.hp/old.hp;e.parts.max*=next.hp/old.hp;}e.attackScale*=next.damage/old.damage;}this.s.difficulty=d;}
