 invalid(kind:string,col:number,layer?:number){const c=this.config.buildings[kind];if(!c)return '请选择建筑';if(!this.buildingUnlocked(kind))return '此建筑尚未在本关解锁';if(this.buildingCount(kind)>=this.buildingLimit(kind))return `${c.name}已达上限 ${this.buildingLimit(kind)} 座`; if(!Number.isInteger(col)||col<this.minColumn||col>=this.config.world.columns)return '超出建造区域';if(this.s.gold<c.cost)return '金币不足';if(this.s.dropCooldown>1e-7)return '吊装冷却中';if(this.s.buildings.some(b=>Math.floor(b.x)===col&&!b.settled&&b.hp>0))return '该列正在下落 / 坍塌';if(kind==='bridge'){if(layer===undefined||!Number.isInteger(layer)||layer<0||layer>=this.config.world.layers)return '请选择桥梁高度';if((col===1||col===2)&&layer<2||this.s.buildings.some(b=>b.hp>0&&Math.floor(b.x)===col&&Math.abs(b.y-(layer+.5))<1))return '该格已被占用';const candidate:Building={id:-1,type:'bridge',x:col+.5,y:layer+.5,hp:1,settled:true,branch:-1,spent:0,v:0,fallId:1,hit:[],cooldown:0};if(!supportedBuildings([...this.s.buildings,candidate]).has(-1))return '需要连接地面、核心或已支撑建筑';return '';}if(this.top(col)>=this.config.world.layers)return '该列已达到最高层';return '';}
