 private structure(){const supported=supportedBuildings(this.s.buildings);for(const b of this.s.buildings){if(b.hp>0&&b.settled&&!supported.has(b.id)){b.settled=false;b.v=0;b.fallId++;b.hit=[];}}for(let col=this.minColumn;col<this.config.world.columns;col++){let top=col===1||col===2?2:0;let supportSettled=true;const stack=this.s.buildings.filter(b=>b.hp>0&&Math.floor(b.x)===col).sort((a,b)=>a.y-b.y||a.id-b.id);for(const b of stack){if(b.settled&&!supported.has(b.id)&&(!supportSettled||b.y-.5>top+1e-6)){b.settled=false;b.v=0;b.fallId++;b.hit=[];}
 if(!b.settled){const prev=b.y;b.v=Math.min(this.config.world.maxVelocity,b.v+this.config.world.gravity*DT);b.y=Math.max(top+.5,b.y-b.v*DT);for(const e of this.index.query(b.x,(prev+b.y)/2,Math.max(2,prev-b.y+2))){const p=this.config.enemies[e.type];if(e.hp>0&&!b.hit.includes(e.id)&&Math.abs(e.x-b.x)<=.5+p.width/2&&e.y+p.height/2>=b.y-.5&&e.y-p.height/2<=prev+.5){b.hit.push(e.id);this.hurtEnemy(e,this.stats(b).impact*(1+this.perk('impact')),'impact');}}if(supportSettled&&b.y<=top+.5+1e-7){b.y=top+.5;b.v=0;b.settled=true;this.emit('dust',b.x,b.y);}}
 top=b.y+.5;supportSettled=b.settled;}}
 for(const e of this.s.enemies){const p=this.config.enemies[e.type];if(this.isAir(e)||e.hp<=0||e.type==='sandworm'||e.type==='leviathan'&&this.s.campaign?.timelineVersion===3||e.type==='burrow_nest'&&e.state==='burrow')continue;let changed=true;while(changed){changed=false;for(const b of this.obstacles()){if(e.x-p.width/2<b.x+b.w/2-1e-7&&e.x+p.width/2>b.x-b.w/2+1e-7){e.x=e.side==='left'?b.x-b.w/2-p.width/2:b.x+b.w/2+p.width/2;changed=true;}}}}
 }
