 private hurtEnemy(e:Enemy,damage:number,kind='physical'){if(!this.targetable(e)||!this.s.alive)return;if(kind==='explosion'&&e.type==='blastbeetle')damage*=1-this.config.schedule.blastResistance;const cover=kind==='friendlyBlast'?undefined:this.escortAnchor(e,true);if(cover){const intercepted=Math.min(cover.shield,damage*(this.config.schedule.shieldCoverShare??.7));cover.shield-=intercepted;damage-=intercepted;if(cover.shield<=0)this.emit('shieldBreak',cover.x,cover.y);}const shield=Math.min(e.shield,damage);e.shield-=shield;if(shield>0&&e.shield===0)this.emit('shieldBreak',e.x,e.y);damage-=shield;if(damage>0){let hit=Math.max(1,damage*(kind==='physical'?1-e.armor:1));if(e.type==='leviathan'&&e.hp<=e.maxHp*.5)hit*=1.15;if(e.type==='carrier'&&e.parts){if(this.partTarget==='core')hit*=this.time<(e.weakUntil??0)?1.6:.65;else if(this.partTarget==='hangar'||this.partTarget==='missiles'){const part=this.partTarget;if(e.parts[part]>0){e.parts[part]=Math.max(0,e.parts[part]-hit);if(e.parts[part]===0){this.emit('mechBurst',e.x,e.y);this.announce('母舰部位摧毁',part==='hangar'?'机库失效 · 召唤显著减少':'导弹舱失效 · 停止后续齐射');}hit*=.65;}}}e.hp-=hit;}if(e.hp<=0){e.hp=0;this.s.gold+=e.reward;this.s.kills++;if(this.config.enemies[e.type].boss){this.s.bossKills++;this.s.lastBossDeath=this.time;if(!this.s.campaign)this.s.perkQueue++;this.s.shots=this.s.shots.filter(s=>s.owner!==e.id||s.phase==='flight');}this.mechanicalDeath(e);if(e.type==='leviathan')this.emit('tidalRise',e.x,0);this.emit('kill',e.x,e.y,e.x,e.y,'+'+e.reward);}}
 private hurtFriend(id:number,amount:number,attacker?:Enemy){if(!this.s.alive)return;if(id===0){this.s.coreHp=Math.max(0,this.s.coreHp-amount);if(this.s.coreHp<=0){this.s.alive=false;this.s.candidates=[];this.s.perkQueue=0;this.demolition=null;this.emit('failure',2,1);}return;}const b=this.s.buildings.find(b=>b.id===id);if(!b||b.hp<=0)return;b.hp=Math.max(0,b.hp-amount);this.emit('hit',b.x,b.y);if(attacker&&this.stats(b).thorns)this.hurtEnemy(attacker,this.stats(b).thorns,'true');}
