 spawn(type:string,eliteAllowed=true,x=35.5,y?:number,eventUnit=false){if(type==='leviathan'&&(!this.s.campaign||this.s.campaign.timelineVersion===3&&(this.s.campaign.revealFrame??0)<720))return;if(type==='sandworm'&&!this.s.campaign&&this.time<900)return;if(!this.s.campaign&&this.s.difficulty==='hard'&&this.s.bossCount===0&&this.config.enemies[type]?.boss&&this.config.enemies.beast){type='beast';y=undefined;}const p=this.config.enemies[type];if(!p)return;if(this.chapter&&!this.chapter.enemies.includes(type)&&!this.chapter.bosses.includes(type))return;if(type==='burrow_nest'&&this.s.enemies.filter(a=>a.type===type&&a.hp>0).length>=2)return;if(type==='burrow_nest'){x=this.s.buildings.filter(b=>b.hp>0&&b.settled&&b.x>=0).sort((a,b)=>b.spent-a.spent||a.id-b.id)[0]?.x??18.5;y=0;}if(type==='fortress'&&this.s.enemies.filter(a=>a.type==='fortress'&&a.hp>0).length>=(this.config.schedule.fortressCap??2))return;if(p.boss&&this.s.enemies.filter(a=>a.hp>0&&this.config.enemies[a.type].boss).length>=(this.chapter?.bosses.length??1))return;if(!p.boss&&this.s.enemies.filter(e=>e.hp>0&&!this.config.enemies[e.type].boss).length>=this.config.schedule.enemyCap-(eventUnit?0:(this.config.schedule.eventReserve??0)))return;const l=this.level-1,difficulty=this.difficultyStats(),growth=this.enemyGrowth(l);let maxHp=p.hp*difficulty.hp*growth.hp,attackScale=growth.damage*difficulty.damage,reward=p.reward,armor=p.armor,shield=0,elite='';if(p.boss){this.s.bossCount++;maxHp*=1+(this.config.schedule.bossHpGrowth??.15)*(this.s.bossCount-1);attackScale*=1+(this.config.schedule.bossDamageGrowth??0)*(this.s.bossCount-1);}else if(eliteAllowed&&this.level>=6&&random(this.s)<Math.min(.45,this.config.schedule.eliteChance+(this.config.schedule.eliteGrowth??0)*l)){maxHp*=1.8;attackScale*=1.25;reward*=2;elite=random(this.s)<.5?'shield':'armor';if(elite==='shield')shield=maxHp*.3;else armor=Math.min(.6,armor+.2);}
 if(type==='leviathan')maxHp=lordHealth(this.config);if(p.boss)shield=maxHp*(this.config.schedule.bossEntryShield??0);if(type==='reflector')shield=maxHp/ p.hp*this.config.schedule.reflectShield;if(type==='leviathan'){if(this.s.campaign)this.s.campaign.storm=true;shield=0;this.emit('tidalRise',x,0);}if(p.boss)this.announce(p.name+' · 已抵达',type==='leviathan'?'深海巨影 / 潮汐冲击 · 注意蓝色落点，准备拦截深水雷':type==='sandworm'?'地下钻出 / 沿途摧毁 · 注意垂直危险通道':type==='queen'?'孵化虫群 / 酸液喷射 · 配置混合火力':type==='tempest'?'连锁落雷 / 等离子弹 · 广域防空就位':type==='beast'?'破城冲撞 / 范围震击 · 分散后排、加固前墙':'空域封锁 / 导弹齐射 · 防空火力就位');
 this.s.enemies.push({parts:type==='carrier'&&this.config.schedule.carrierParts?{hangar:maxHp*this.config.schedule.carrierParts,missiles:maxHp*this.config.schedule.carrierParts,max:maxHp*this.config.schedule.carrierParts}:undefined,id:this.s.nextEntityId++,type,x,y:y??(type==='carrier'?11:type==='tempest'?9:type==='bombardier'?10:type==='suicide_ship'?8:type==='fortress'?6.5:p.air?5:p.height/2),hp:maxHp,maxHp,shield,armor,attackScale,speedScale:Math.min(1.3,1+this.config.schedule.speedGrowth*l),reward,elite,special:p.boss?this.config.schedule.bossOpeningDelay:undefined,secondary:p.boss?(this.config.schedule.bossOpeningDelay===undefined?undefined:this.config.schedule.bossOpeningDelay+1):undefined,cooldown:type==='bombardier'?4:0,slows:[],skill:type==='carrier'?4:12,summon:type==='leviathan'?6:type==='carrier'?3:type==='fortress'?4:15,state:type==='burrow_nest'?'burrow':'walk',timer:type==='burrow_nest'?6:0,distance:0,target:0});if(type==='burrow_nest'){this.s.enemies[this.s.enemies.length-1].elite='brood';this.announce('地渊孵化兽 / 地底巢穴接近','6 秒后破土摧毁出土区域建筑 · 立即吊装撤离，出土后集火');}}
